"""Internal Numba implementation of the Lempel-Ziv (LZ) complexity.
    https://github.com/Naereen/Lempel-Ziv_Complexity/blob/master/src/lziv_complexity.py
    - Updated with strict integer typing instead of strings
    - Slight restructuring based on Yacine Mahdid's notebook:
    https://github.com/BIAPT/Notebooks/blob/master/features/Lempel-Ziv%20Complexity.ipynb
    """
def _lz_complexity(binary_string: Any) -> object {
    complexity = 1;
    prefix_len = 1;
    len_substring = 1;
    max_len_substring = 1;
    pointer = 0;
    while ((prefix_len + len_substring) <= len(binary_string)) {
        if (
            binary_string[((pointer + len_substring) - 1)]
            == binary_string[((prefix_len + len_substring) - 1)]
        ) {
            len_substring += 1;
        } else {
            max_len_substring = max(len_substring, max_len_substring);
            pointer += 1;
            if (pointer == prefix_len) {
                complexity += 1;
                prefix_len += max_len_substring;
                pointer = 0;
                max_len_substring = 1;
            }
            len_substring = 1;
        }
    }
    if (len_substring != 1) {
        complexity += 1;
    }
    return complexity;
}

"""Return a string to be used as a placeholder for an empty option.

    The length of the placeholder is based on the length of the longest
    option in a list of entries.
    """
def construct_none_displayer(entries: Any, placeholder: Any = '-') -> object {
    entries = [str(e) for e in entries];
    max_len = len(max(entries, key=len));
    if (max_len > 4) {
        none_dislplayer = placeholder * (max_len + 1);
    } else {
        none_dislplayer = placeholder * 5;
    }
    return none_dislplayer;
}

"""
    Iterates iterable and returns a list of dictionaries with keys and values converted to Unicode

    >>> gen = ({'0': None, 2: 'two', '3': 0xc0ffee} for i in range(3))
    >>> get_unicode_dicts(gen)
    [{'2': 'two', '0': None, '3': '12648430'},
     {'2': 'two', '0': None, '3': '12648430'},
     {'2': 'two', '0': None, '3': '12648430'}]

    """
def get_unicode_dicts(iterable: Any) -> object {
    def none_or_unicode(val: Any) -> object {
        return str(val) if (val is not None) else val;
    }
    rows = [];
    for row in iterable {
        rows.append({str(k): none_or_unicode(v) for (k, v) in row.items()});
    }
    return rows;
}

"""
    This is a hacky function for getting the precision to use when comparing
    the value sent to WF via the proxy with a double value passed to it.
    Arguments:
    value - the value to return the precision to use with a %.E format string
    """
def get_precision(value: Any) -> object {
    sval = '%.2f' % float(value);
    last_index = len(sval);
    found_decimal = False;
    for index in range((len(sval) - 1), 0, -1) {
        char = sval[index];
        last_index = index;
        if (char == '.') {
            found_decimal = True;
        }
        if ((char != '0') and (char != '.')) {
            break;
        }
    }
    if not found_decimal {
        return (last_index - 1);
    } else {
        return last_index;
    }
}

